function save(manual=false){if(!entryAuthorized)return false;try{if(saveBlocked)throw Error('기존 저장본 보호 중입니다. 저장·불러오기에서 복원해 주세요.');writeProgress(localStorage,state);$('#save-status').textContent='전체 저장 중…';queueFullSave().then(()=>{$('#save-status').textContent='전체 저장 '+new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});if(manual)toast('게임·이미지·프롬프트를 함께 저장했습니다.');}).catch(()=>{});return true;}catch(error){if(!saveWarning||manual)toast(error.message||'저장에 실패했습니다. 파일로 내보내 주세요.',true);saveWarning=true;$('#save-status').textContent='저장 확인 필요';return false;}}
function progressHTML(){let slots='';for(let n=1;n<=3;n++){let summary='비어 있음',exists=false;try{if(fullSlots[n]){const bundle=fullSlots[n];summary=new Date(bundle.time).toLocaleString('ko-KR')+' · 선원 '+bundle.state.crew.roster.length+'명 · 이미지 '+bundle.images.reduce((v,r)=>v+r.versions.length,0)+'장 · 전체 저장';exists=true;}else {const raw=localStorage.getItem(slotKey(n));if(raw){const value=JSON.parse(raw),s=decodeSave(JSON.stringify(value.state));summary=new Date(value.time).toLocaleString('ko-KR')+' · D'+(Math.floor(s.hours/24)+1)+' · 선원 '+s.crew.roster.length+'명';exists=true;}}}catch{summary='손상된 저장본 · 파일 복원 필요';}slots+=`<article class="progress-slot"><h3>슬롯 ${n}</h3><p>${esc(summary)}</p><div class="actions"><button data-progress-save="${n}">현재 진행 저장</button><button data-progress-load="${n}" ${exists?'':'disabled'}>불러오기</button></div></article>`;}return `<section><p class="hint">게임 진행·승무원·이미지 원본과 적용 상태·프롬프트를 함께 저장합니다. 슬롯과 내보내기 파일도 동일한 전체 저장본입니다. 클라우드는 같은 내용을 서버에 보관합니다. 구버전 슬롯은 게임 진행만 포함하며 기존 이미지를 지우지 않습니다.</p><div class="actions"><button data-progress-auto>최근 자동 저장 불러오기</button><button data-progress-backup>이전 자동 백업 불러오기</button><button data-progress-before>복원 전 전체 백업 불러오기</button><button data-progress-export>전체 저장 파일 내보내기</button><label class="progress-import">게임 파일 불러오기<input id="progress-import" type="file" accept=".json,application/json"></label><button data-data-section="cloud">클라우드 보관함</button></div>${slots}</section>`;}
function restoreProgress(bundle){const next=bundle.state;if(busy||generating||imagePending||cloud.busy)throw Error('진행 중인 작업이 끝난 뒤 불러오세요.');setSpeed(0);const modal=$('#modal');modal.innerHTML=`<h2>저장된 진행을 불러올까요?</h2><p>${bundle.legacy?'구버전 게임 저장입니다. 이미지·프롬프트는 포함되어 있지 않아 현재 보관함을 유지합니다.':'게임·이미지 적용 상태·프롬프트를 함께 복원합니다.'} 현재 기록을 전체 백업합니다.</p><div class="actions"><button id="cancel-load">취소</button><button id="confirm-load" class="primary">불러오기</button></div>`;modal.showModal();$('#cancel-load').onclick=()=>modal.close();$('#confirm-load').onclick=async()=>{if(cloud.busy)return;cloud.busy=true;try{await imagesReady;await fullSaveQueue.catch(()=>{});await writeBundle('before-restore',captureBundle());const prior=exportWorldImages(next);try{if(!bundle.legacy)await replaceWorldImages(next,bundle.images);writeProgress(localStorage,next,{replace:true});}catch(error){if(!bundle.legacy)await replaceWorldImages(next,prior);throw error;}if(!bundle.legacy)applyPromptSettings(bundle.settings);state=next;saveBlocked=false;saveWarning=false;selected=state.location;selectedCrew=state.crew.roster[0]?.id||CREW_CANDIDATES[0].id;crewReview='';crewView='aboard';dataContact='';reviewMission='';selectedMission='';for(const k of Object.keys(crewDrafts))delete crewDrafts[k];for(const k of Object.keys(crewAssignments))delete crewAssignments[k];marketDay=Math.floor(state.hours/24);saveElapsed=0;modal.close();render();await writeBundle('auto',captureBundle());toast(bundle.legacy?'구버전 게임 진행을 복원했습니다. 이미지는 기존 보관함을 유지했습니다.':'게임·이미지·프롬프트를 함께 복원했습니다.');}catch(e){toast(e.message,true);}finally{cloud.busy=false;}};}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-progress-save],[data-progress-load],[data-progress-auto],[data-progress-backup],[data-progress-before],[data-progress-export]');if(!b||cloud.busy)return;if(busy||generating||imagePending){toast('진행 중인 작업이 끝난 뒤 저장·복원하세요.',true);return;}setSpeed(0);try{await imagesReady;await fullSaveQueue.catch(()=>{});if(b.dataset.progressSave){const n=Number(b.dataset.progressSave);if((fullSlots[n]||localStorage.getItem(slotKey(n)))&&!confirm('슬롯 '+n+'을 현재 전체 기록으로 교체할까요?'))return;const bundle=captureBundle();await writeBundle('slot-'+n,bundle);fullSlots[n]=bundle;renderDetail();toast('게임·이미지·프롬프트를 슬롯에 저장했습니다.');}else if(b.dataset.progressLoad){const n=Number(b.dataset.progressLoad),bundle=await readBundle('slot-'+n);if(bundle)restoreProgress(bundle);else{const value=JSON.parse(localStorage.getItem(slotKey(n)));restoreProgress({state:decodeSave(JSON.stringify(value.state)),legacy:true});}}else if(b.hasAttribute('data-progress-export')){const blob=new Blob([JSON.stringify(captureBundle())],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='asterion-full-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else{const backup=b.hasAttribute('data-progress-backup');const bundle=await readBundle(b.hasAttribute('data-progress-before')?'before-restore':backup?'backup':'auto');if(!bundle&&b.hasAttribute('data-progress-before'))throw Error('복원 전 전체 백업이 아직 없습니다.');restoreProgress(bundle||{state:decodeSave(localStorage.getItem(KEY+(backup?'-backup':''))),legacy:true});}}catch(error){toast(error.message,true);}});
document.addEventListener('change',async e=>{if(e.target.id!=='progress-import')return;const file=e.target.files[0];if(!file)return;try{if(file.size>105000000)throw Error('105MB 이하 전체 저장 파일을 선택하세요.');restoreProgress(decodeBundle(await file.text()));}catch(error){toast(error.message,true);}e.target.value='';});
