function renderStats(){const shipFooter=$('.workspace-panel-foot>span');if(shipFooter)shipFooter.textContent='CSV '+activeDesign(state).name+' / COMMAND INTERFACE';const hazard=activeRouteAlert(state);document.body.classList.toggle('route-caution',!!hazard&&!hazard.active);document.body.classList.toggle('route-danger',!!hazard?.active);const warning=$('#route-warning');warning.hidden=!hazard;const hazardKey=hazard?[hazard.id,hazard.created,hazard.active].join(':'):'';if(hazardKey!==lastRouteWarning){lastRouteWarning=hazardKey;if(hazard&&!hazard.active)toast((hazard.reporter?crewMember(hazard.reporter,state)?.name:'항로 센서')+' 경고: 전방 '+hazard.title);}if(hazard)warning.textContent='⚠ '+(hazard.active?'항로 이상 발생: ':'전방 위험 감지: ')+hazard.title+' · '+(hazard.active?'대응을 선택하세요':(hazard.reporter?crewMember(hazard.reporter,state)?.name+'의 경고':'센서 보고')+' / 항법 패널 확인');if(hazard?.reporter&&!hazard.active&&canContactCrew(state,hazard.reporter)){warning.dataset.contactId=hazard.reporter;delete warning.dataset.tab;const src=imageSource(state,'person:'+hazard.reporter);if(src){const avatar=document.createElement('img');avatar.src=src;avatar.referrerPolicy='no-referrer';avatar.alt='경고를 보낸 승무원';warning.prepend(avatar);}warning.append(document.createTextNode(' · 눌러서 개인 통신'));}else{delete warning.dataset.contactId;warning.dataset.tab='navigation';}if(workspacePanel.open){if(tab==='crew')readCrew(state,selectedCrew);if(tab==='data'&&dataSection==='contacts'&&dataContact)readCrew(state,dataContact);}const stats=[['보유 자금',fmt(state.credits),'CR','assets'],['연료',fmt(state.fuel),'/ 100','ship'],['화물',usedCargo(state),'/ '+cargoCapacity(state)+'t','market'],['탐사',placesFor(state).filter(p=>LOCATION_TYPES[p.type].survey&&(state.survey[p.id]||0)>0).length,'/ '+placesFor(state).filter(p=>LOCATION_TYPES[p.type].survey).length,'log']];$('#stats').innerHTML=stats.map(([label,value,unit,target])=>`<button class="bridge-stat" data-tab="${target}" aria-haspopup="dialog"><span>${label}</span><strong>${value}<small>${unit}</small></strong></button>`).join('');const alert=$('#bridge-alert');alert.hidden=!state.event;alert.dataset.tab=state.combat?.status==='active'?'combat':'navigation';const radioNav=$('#nav [data-tab="comms"] small');if(radioNav){const n=state.comms.channels.reduce((n,c)=>n+unread(c),0);radioNav.textContent=n?'통신 · '+n:'통신';}const crewNav=$('#nav [data-tab="crew"] small');if(crewNav){const count=state.crew.roster.reduce((n,m)=>n+crewUnread(state,m.id),0);crewNav.textContent=count?'승무원 · '+count:'승무원';}const peopleMenu=$('#nav [data-menu="people"]');if(peopleMenu){const unreadCount=state.comms.channels.reduce((n,c)=>n+unread(c),0);let badge=peopleMenu.querySelector('.menu-unread');if(unreadCount){if(!badge){badge=document.createElement('b');badge.className='menu-unread';peopleMenu.append(badge);}badge.textContent=unreadCount;badge.setAttribute('aria-label','미확인 통신 '+unreadCount+'건');}else badge?.remove();}if(state.event)alert.textContent=`⚠ ${state.event.title} · 대응 패널 열기 →`;}
