async function issueCombatOrder(action){
 if(combatAnimating)return;
 const root=$('.combat-console');let receipt=null;
 try{
  const before=outcomeSnapshot(state),result=combatOrder(state,action);save();combatAnimating=true;
  if(result.status!=='active')receipt=combatResult(state,before);
  root?.querySelectorAll('[data-combat-order]').forEach(b=>b.disabled=true);
  await playCombatEffects(root,result.effects||[]);
 }catch(e){toast(e.message,true);}
 finally{combatAnimating=false;if(receipt)showResultFeedback($('#result-feedback'),receipt);render();}
}
