function showHelp(){closePanel();setSpeed(0);$('#modal').innerHTML=`<div class="eyebrow">WELCOME ABOARD, CAPTAIN</div><h2>노마드에 오신 것을 환영합니다.</h2><p>목표는 함장님이 정합니다. 무역으로 자금을 모으거나, 유적을 탐사하거나, 채굴 전초기지를 운영해 보세요.</p><ul><li>지도에서 목적지 선택 → 항로 설정 및 출항</li><li>1× · 4× · 12×로 시간 진행, Ⅱ로 정지</li><li>도착하면 탐사·교역·보급을 진행하세요.</li><li>통신에서 연합 계약을 수락하면 첫 보수 650 CR을 얻을 수 있습니다.</li><li>왼쪽 메뉴를 누르면 전용 패널이 열리고 시간이 정지합니다. ESC 또는 닫기로 지도로 돌아갑니다.</li><li>진행은 이 브라우저에 자동 저장됩니다. 창을 닫으면 시간이 흐르지 않습니다.</li></ul><p class="hint">AI 키가 없으면 로컬 통신으로 플레이합니다. 이번 버전은 자유 항해·교역·탐사·기지 운영 프로토타입입니다.</p><div class="actions"><button class="primary" id="close-modal">함교로 진입 →</button></div>`;$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();}
$('#help').onclick=showHelp;
$('#reset').onclick=()=>{if(busy||generating||imagePending||cloud.busy){toast('진행 중인 작업이 끝난 뒤 새 항해를 시작하세요.',true);return;}setSpeed(0);closePanel();$('#modal').innerHTML='<h2>새로운 항해를 시작할까요?</h2><p>현재 게임·이미지·프롬프트를 전체 백업한 뒤 새로운 우주에서 시작합니다. 기존 슬롯과 클라우드 저장본은 보존됩니다.</p><div class="actions"><button id="cancel-reset">취소</button><button class="primary" id="confirm-reset">백업 후 새로 시작하기</button></div>';$('#modal').showModal();$('#cancel-reset').onclick=()=>$('#modal').close();$('#confirm-reset').onclick=async()=>{if(cloud.busy)return;cloud.busy=true;$('#confirm-reset').disabled=true;try{await imagesReady;await fullSaveQueue.catch(()=>{});await writeBundle('before-restore',captureBundle());const next=freshState();writeProgress(localStorage,next,{replace:true});state=next;saveBlocked=false;saveWarning=false;selected=state.location;tab='navigation';chartPoint='';confirmPurchase=false;dataSection='home';dataContact='';selectedCrew=CREW_CANDIDATES[0].id;crewView='aboard';crewReview='';crewPromptSuggestion=null;for(const target of [crewDrafts,crewAssignments])for(const key of Object.keys(target))delete target[key];reviewMission='';selectedMission='';marketDay=0;saveElapsed=0;newsSignature='';save();await fullSaveQueue;render();$('#modal').close();cloud.busy=false;await entry.playNew();}catch(error){toast(error.message,true);$('#confirm-reset').disabled=false;}finally{cloud.busy=false;}};};

let last=performance.now(),saveElapsed=0,marketDay=Math.floor(state.hours/24);setInterval(()=>{const now=performance.now(),elapsed=Math.min((now-last)/1000,1);last=now;if(!speed||busy){syncUrgent();return;}const wasTravel=!!state.travel;tick(state,elapsed*speed);if(state.event||(wasTravel&&!state.travel)){setSpeed(0);save();if(!state.event){selected=state.location;confirmPurchase=false;openPanel('navigation');toast(`${place(state.location,state).name} 도착. 시간이 정지되었습니다.`);}else{openPanel(state.combat?.status==='active'?'combat':'navigation');toast(`${state.event.title} · 대응을 선택하세요.`);}render();}else{renderNews();renderStats();renderMap();renderTime();if(tab==='shipyard'||tab==='assets'||(tab==='market'&&marketDay!==Math.floor(state.hours/24)))renderDetail();marketDay=Math.floor(state.hours/24);refreshRadio();renderShip();}syncUrgent();saveElapsed+=elapsed;if(saveElapsed>3){save();saveElapsed=0;}},500);
