document.addEventListener('click',async e=>{const b=e.target.closest('[data-mission-brief],[data-mission-brief-clear]');if(!b)return;if(busy||cloud.busy||imagePending||generating){toast('진행 중인 작업이 끝난 뒤 설명을 생성하세요.',true);return;}const id=b.dataset.missionBrief||b.dataset.missionBriefClear;if(!missionTemplate(id))return;if(b.dataset.missionBriefClear){delete state.missions.briefs?.[id];save();renderDetail();return;}if(state.missions.briefs?.[id])return;const origin=state,started=performance.now(),time=Date.now(),requestId=crypto.randomUUID();let metadata=null,ok=false;setSpeed(0);busy=true;missionBriefPending=id;renderDetail();try{const response=await fetch('/api/mission-brief',{method:'POST',headers:{'Content-Type':'application/json','x-game-access-code':accessCode},body:JSON.stringify({template:id}),signal:AbortSignal.timeout(28000)});metadata=await response.json();if(!response.ok)throw Error(metadata.error||'의뢰 설명 생성 실패');if(state!==origin)return;storeMissionBrief(state,id,metadata);save();ok=true;toast('AI 의뢰 설명을 저장했습니다. 실제 임무 조건은 유지됩니다.');}catch(error){toast(error.message,true);}finally{trackRequest({id:requestId,time,duration:performance.now()-started,faction:'mission-brief',mode:metadata?.mode||'unknown',model:metadata?.model||'gpt-6-luna',usage:metadata?.usage,ok});busy=false;missionBriefPending='';renderDetail();}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-yard-review],[data-yard-confirm],[data-yard-cancel],[data-yard-action],[data-yard-wait]');if(!b)return;if(busy||cloud.busy||imagePending||generating||combatAnimating){toast('진행 중인 작업이 끝난 뒤 조선소를 이용하세요.',true);return;}if(b.hasAttribute('data-yard-cancel')){yardReview=null;renderDetail();return;}if(b.dataset.yardReview){yardReview={action:b.dataset.yardReview,id:b.dataset.yardId};renderDetail();$('#detail').querySelector('.yard-review')?.scrollIntoView({block:'start',behavior:'smooth'});return;}setSpeed(0);act(()=>{if(b.hasAttribute('data-yard-wait')){if(state.event||state.travel)throw Error('안전하게 정박한 뒤 기다리세요.');tick(state,1);}else{const command=b.hasAttribute('data-yard-confirm')?yardReview:{action:b.dataset.yardAction,id:b.dataset.yardId};if(!command)throw Error('작업 내용을 먼저 확인하세요.');toast(shipyardOrder(state,command.action,command.id));yardReview=null;}if(state.event){selected=state.event.location||state.location;openPanel('navigation');}});});

// Inventory browsing changes only the interface, never the saved item quantities.
document.addEventListener('click',e=>{const b=e.target.closest('[data-material-select],[data-material-filter]');if(!b)return;if(b.dataset.materialSelect)materialSelection=b.dataset.materialSelect;else materialFilter=b.dataset.materialFilter;renderDetail();const selector=b.dataset.materialSelect?'[data-material-select="'+b.dataset.materialSelect+'"]':'[data-material-filter="'+materialFilter+'"]';document.querySelector(selector)?.focus({preventScroll:true});});

document.addEventListener('click',e=>{const b=e.target.closest('[data-craft-back],[data-craft-category],[data-craft-recipe],[data-craft-review],[data-craft-confirm],[data-craft-cancel],[data-craft-track]');if(!b||cloud.busy)return;
 if(b.hasAttribute('data-craft-back')){craftReview=null;const prev=craftHistory.pop();if(prev){craftCategory=prev.category;craftSelected=prev.selected;craftCount=prev.count;craftSource=prev.source;craftMobileView='detail';renderDetail();$('#detail').scrollTop=prev.scroll;}else{craftMobileView='list';renderDetail();$('#detail').scrollTop=craftListScroll;}return;}
 if(b.hasAttribute('data-craft-confirm')){if(!craftReview)return;const order={...craftReview};act(()=>{const message=craftingOrder(state,order);craftReview=null;craftSource='';toast(message);});return;}
 if(b.hasAttribute('data-craft-cancel')){craftReview=null;renderDetail();return;}
 craftReview=null;
 if(b.dataset.craftCategory){craftMobileView='list';craftHistory=[];craftListScroll=0;craftCategory=b.dataset.craftCategory;craftSelected=RECIPES.find(r=>r.category===craftCategory)?.id||'';craftSource='';craftCount=1;}
 if(b.dataset.craftRecipe){if(matchMedia('(max-width:700px)').matches){if(dataSection==='crafting'&&craftMobileView==='detail'&&!b.closest('.craft-recipes'))craftHistory.push({category:craftCategory,selected:craftSelected,count:craftCount,source:craftSource,scroll:$('#detail').scrollTop});else{craftHistory=[];craftListScroll=dataSection==='crafting'?$('#detail').scrollTop:0;}}craftMobileView='detail';dataSection='crafting';const r=recipe(b.dataset.craftRecipe);if(!r)return;craftSelected=r.id;if(!b.hasAttribute('data-craft-salvage-list'))craftCategory=r.category;craftSource='';craftCount=1;}
 if(b.dataset.craftTrack){act(()=>toast(craftingOrder(state,{action:'track',id:b.dataset.craftTrack==='clear'?null:b.dataset.craftTrack})));return;}
 if(b.dataset.craftReview)craftReview={action:b.dataset.craftReview,id:b.dataset.craftId,count:recipe(b.dataset.craftId)?.gear?1:craftCount,source:craftSource};
 renderDetail();if(b.dataset.craftRecipe){if(matchMedia('(max-width:700px)').matches){$('#detail').scrollTop=0;document.querySelector('[data-craft-back]')?.focus({preventScroll:true});}else document.querySelector('.craft-detail')?.scrollIntoView({block:'nearest'});}
});
document.addEventListener('change',e=>{if(e.target.id!=='craft-count'&&e.target.id!=='craft-source')return;craftReview=null;if(e.target.id==='craft-count')craftCount=Number(e.target.value);else craftSource=e.target.value;renderDetail();document.querySelector(e.target.id==='craft-count'?'#craft-count':'#craft-source')?.focus({preventScroll:true});});

document.addEventListener('click',e=>{const b=e.target.closest('[data-upgrade-branch],[data-upgrade-review],[data-upgrade-confirm],[data-upgrade-cancel]');if(!b)return;if(busy||cloud.busy||imagePending||generating||combatAnimating){toast('진행 중인 작업이 끝난 뒤 개조 도크를 이용하세요.',true);return;}
 if(b.hasAttribute('data-upgrade-confirm')){if(!upgradeReview)return;const order={...upgradeReview};act(()=>{toast(upgradeOrder(state,order));upgradeReview=null;});return;}
 upgradeReview=null;if(b.dataset.upgradeBranch)upgradeBranch=b.dataset.upgradeBranch;
 if(b.dataset.upgradeReview){upgradeBranch=b.dataset.upgradeReview;const st=upgradeStatus(state,upgradeBranch);if(!st.eligible){toast(st.reason,true);return;}upgradeReview={branch:upgradeBranch,design:st.quote.design,level:st.quote.next};}
 renderDetail();
});

document.addEventListener('toggle',e=>{if(e.target.isConnected&&e.target.matches?.('[data-mission-fold]'))missionFoldState.set(e.target.dataset.missionFold,e.target.open);},true);

function renderCommsDock(force=false){
 const root=$('#comms-dock');if(!root)return;root.hidden=!entryAuthorized||document.body.classList.contains('entry-active');
 const signature=JSON.stringify([dockOpen,dockExpanded,dockSettings,dockGroup,radioAddOpen,state.comms.sequence,state.comms.active,state.comms.channels.map(c=>[c.id,c.aiLevel,c.readAt,c.messages.length]),busy,speed]);if(!force&&signature===dockSignature)return;dockSignature=signature;
 const old=$('#radio-feed'),same=old?.dataset.channel===state.comms.active,atBottom=!same||old.scrollHeight-old.scrollTop-old.clientHeight<65,scroll=old?.scrollTop||0,typing=document.activeElement?.id==='message',selection=typing?document.activeElement.selectionStart:null;
 root.className='comms-dock'+(dockOpen?' dock-open':'')+(dockExpanded?' dock-expanded':'')+(dockSettings?' dock-settings':'');root.innerHTML=dockChrome(state,{open:dockOpen,expanded:dockExpanded,group:dockGroup,settings:dockSettings});
 if(!dockOpen)return;const conversation=$('#dock-conversation');
 if(dockGroup==='personal'){conversation.innerHTML='<div class="dock-personal"><p>승무원 개인 대화</p>'+state.crew.roster.map(m=>{const c=crewMember(m.id,state);return `<button data-open-crew="${esc(c.id)}">${esc(c.name)} · 개인 대화 →</button>`;}).join('')+'<button data-data-section="contacts">전체 인물·담당관 연락처 →</button></div>';return;}

 conversation.innerHTML=commsHTML(state,{busy,channel,accessCode,draft:radioDrafts[state.comms.active]||'',addOpen:radioAddOpen,speed,FACTIONS});
 const feed=$('#radio-feed');if(feed){feed.dataset.channel=state.comms.active;feed.setAttribute('aria-live','off');feed.scrollTop=atBottom?feed.scrollHeight:scroll;$('#comms-dock [data-dock-latest]').hidden=atBottom;if(atBottom)markRead(state);feed.addEventListener('scroll',()=>{const bottom=feed.scrollHeight-feed.scrollTop-feed.clientHeight<65;$('#comms-dock [data-dock-latest]').hidden=bottom;if(bottom)markRead(state);});}
 if(typing&&!busy){const input=$('#message');input?.focus({preventScroll:true});if(selection!==null)input?.setSelectionRange(selection,selection);}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-dock-toggle],[data-dock-expand],[data-dock-settings],[data-dock-group],[data-dock-latest]');if(!b||cloud.busy)return;
 if(b.hasAttribute('data-dock-toggle'))dockOpen=!dockOpen;
 if(b.hasAttribute('data-dock-expand'))dockExpanded=!dockExpanded;
 if(b.hasAttribute('data-dock-settings'))dockSettings=!dockSettings;
 if(b.hasAttribute('data-dock-latest')){const f=$('#radio-feed');if(f){f.scrollTop=f.scrollHeight;markRead(state);}return;}
 if(b.dataset.dockGroup){dockGroup=b.dataset.dockGroup;if(dockGroup!=='personal'){const c=state.comms.channels.find(c=>dockGroup==='public'?c.kind==='public':c.kind==='direct');if(c)selectChannel(state,c.id);}}
 renderCommsDock(true);
});
document.addEventListener('change',e=>{if(e.target.id==='dock-channel'){act(()=>selectChannel(state,e.target.value));}});
